deltas.after:
.topic-values {display:flex;flex-wrap:wrap;gap:16px;margin:20px 0;}
.topic-values>div {flex:1 1 max-content;min-width:0;max-width:100%;}
.topic-values small,.topic-values span {display:block;font-size:12px;color:var(--mcn-muted);}
.topic-values strong {display:inline;font-size:1.6875rem;font-weight:650;font-variant-numeric:tabular-nums;color:var(--mcn-ink);}
.topic-number-shell {min-width:0;max-width:100%;}
.topic-number {max-width:100%;overflow-x:auto;white-space:nowrap;overflow-wrap:normal;line-height:1.4;margin:6px 0;padding-block:2px;}
.topic-values .topic-number-content {display:inline-block;white-space:nowrap;overflow-wrap:normal;}
.topic-values .topic-number-unit {display:inline;margin-left:.375rem;font-size:.75rem;font-weight:400;}
.topic-number:focus-visible {outline:2px solid var(--ring);outline-offset:2px;border-radius:2px;}
.topic-values .topic-number-hint {white-space:normal;overflow-wrap:normal;line-height:1.5;}
.topic-delta {margin-top:8px;}
.topic-delta .topic-number {margin:2px 0;}
.topic-delta strong {font-size:.875rem;font-weight:500;}
